import{requireUser}from"@/lib/auth/guards";import{db}from"@/lib/db";import{avatarAction,changeEmailAction,changePasswordAction}from"@/app/actions";export const dynamic="force-dynamic";export default async function Settings(){const u=await requireUser();const account=await db.user.findUniqueOrThrow({where:{id:u.id},select:{email:true,displayName:true,avatar:{select:{updatedAt:true}}}});return <section className="section settings-page"><div className="section-title"><div><span className="eyebrow">Личный кабинет</span><h1>Настройки аккаунта</h1></div></div><div className="avatar-panel panel"><div className="avatar-preview">{account.avatar?<img src={`/api/avatars/${u.id}?v=${account.avatar.updatedAt.getTime()}`} alt={`Аватар ${account.displayName||"пользователя"}`}/>:<span>{(account.displayName||account.email).slice(0,1).toUpperCase()}</span>}</div><div><h2>Аватар</h2><p>JPG, PNG или WebP, максимум 5 МБ. Изображение будет обрезано до квадрата.</p><form action={avatarAction} className="avatar-form"><input name="avatar" type="file" accept="image/jpeg,image/png,image/webp" required/><button>Загрузить аватар</button></form>{account.avatar&&<form action={avatarAction}><button className="danger" name="op" value="delete">Удалить аватар</button></form>}</div></div><div className="settings-grid"><form className="panel form" action={changeEmailAction}><h2>Изменить email</h2><p>После изменения потребуется войти заново.</p><label>Новый email<input name="email" type="email" defaultValue={account.email} required autoComplete="email"/></label><label>Текущий пароль<input name="currentPassword" type="password" required autoComplete="current-password"/></label><button>Сохранить email</button></form><form className="panel form" action={changePasswordAction}><h2>Изменить пароль</h2><p>Минимум 10 символов: заглавная и строчная буквы, цифра и специальный символ.</p><label>Текущий пароль<input name="currentPassword" type="password" required autoComplete="current-password"/></label><label>Новый пароль<input name="newPassword" type="password" required minLength={10} autoComplete="new-password"/></label><label>Повторите новый пароль<input name="confirmPassword" type="password" required minLength={10} autoComplete="new-password"/></label><button>Сохранить пароль</button></form></div></section>}
